import 'kp_service.dart';

class PalangalService {
  static String getDetailedWeekdayPalan(String? weekdayName) {
    if (weekdayName == null) return "-";
    
    String name = weekdayName.toLowerCase();
    String intro = "நீங்கள் $weekdayName கிழமையில் பிறந்துள்ளீர்கள்.\n\n";

    if (name.contains("ஞாயிறு") || name.contains("sunday")) {
      return "ஞாயிற்றுக்கிழமை (Sunday)\nஅதிபதி: சூரியன்\n\n$intro • தன்மை: நீங்கள் தலைமைப் பண்பு மிக்கவர். எதற்கும் அஞ்சாத நேர்மையும், கம்பீரமும் உங்கள் அடையாளங்கள்.\n• பலன்: சுதந்திரமாகச் செயல்பட விரும்புவீர்கள். எதையும் மேலோட்டமாகப் பார்க்காமல் ஆழமாகச் சிந்திப்பீர்கள். தாராள மனமும், கௌரவமும் கொண்டவர்.\n• வழிபாடு: ஆதித்ய ஹிருதயம் அல்லது சூரிய நமஸ்காரம் செய்வது உங்கள் புகழை வளர்க்கும்.";
    }
    if (name.contains("திங்கள்") || name.contains("monday")) {
      return "திங்கட்கிழமை (Monday)\nஅதிபதி: சந்திரன்\n\n$intro • தன்மை: நீங்கள் மென்மையான இதயம் கொண்டவர். மற்றவர்களின் உணர்வுகளை எளிதில் புரிந்து கொள்வீர்கள்.\n• பலன்: கற்பனை வளம் அதிகம். தாய் மற்றும் குடும்பத்தின் மீது அதிகப் பற்று கொண்டிருப்பீர்கள். அமைதியையும், அன்பையும் விரும்புபவர்.\n• வழிபாடு: சிவபெருமானை அல்லது அம்மனை வழிபட மன அமைதி பெருகும்.";
    }
    if (name.contains("செவ்வாய்") || name.contains("tuesday")) {
      return "செவ்வாய்க்கிழமை (Tuesday)\nஅதிபதி: செவ்வாய்\n\n$intro • தன்மை: நீங்கள் ஒரு போராட்ட குணம் கொண்டவர். சவால்களை எதிர்கொள்வதில் உங்களுக்கு நிகர் நீங்களே.\n• பலன்: அதீத தைரியம், சுறுசுறுப்பு மற்றும் பிடிவாத குணம் இருக்கும். எதையும் வேகமாகச் செய்து முடிக்க விரும்புவீர்கள். இரத்த பந்த உறவுகளுக்கு முக்கியத்துவம் தருவீர்கள்.\n• வழிபாடு: முருகப் பெருமானை வழிபட அனைத்துக் காரியங்களிலும் வெற்றி கிடைக்கும்.";
    }
    if (name.contains("புதன்") || name.contains("wednesday")) {
      return "புதன்கிழமை (Wednesday)\nஅதிபதி: புதன்\n\n$intro • தன்மை: நீங்கள் அறிவாற்றல் மற்றும் பேச்சாற்றல் மிக்கவர். நகைச்சுவை உணர்வு உங்களுக்கு இயல்பிலேயே இருக்கும்.\n• பலன்: எதையும் எளிதில் கற்றுக் கொள்ளும் திறன் கொண்டவர். கணக்கு, எழுத்து மற்றும் தகவல் தொடர்பில் வல்லவர். சிறந்த நண்பர்களைப் பெற்றிருப்பீர்கள்.\n• வழிபாடு: மகாவிஷ்ணுவை வழிபட புத்தி கூர்மை மற்றும் கல்வியில் மேன்மை உண்டாகும்.";
    }
    if (name.contains("வியாழன்") || name.contains("thursday")) {
      return "வியாழக்கிழமை (Thursday)\nஅதிபதி: குரு (வியாழன்)\n\n$intro • தன்மை: நீங்கள் ஞானம் மற்றும் ஒழுக்கம் கொண்டவர். மற்றவர்களுக்கு வழிகாட்டும் ஆசானாகத் திகழ்வீர்கள்.\n• பலன்: நீதி, நேர்மை மற்றும் தெய்வ பக்தி கொண்டவர். மற்றவர்களுக்கு அறிவுரை கூறுவதில் வல்லவர். சமூகத்தில் உங்களை ஒரு பெரிய மனிதராகப் பார்ப்பார்கள்.\n• வழிபாடு: தட்சிணாமூர்த்தி அல்லது சாய் பாபாவை வழிபட அஷ்ட ஐஸ்வர்யங்களும் கிட்டும்.";
    }
    if (name.contains("வெள்ளி") || name.contains("friday")) {
      return "வெள்ளிக்கிழமை (Friday)\nஅதிபதி: சுக்கிரன்\n\n$intro • தன்மை: நீங்கள் கலை ரசனை மிக்கவர். எதிலுமே அழகையும், நேர்த்தியையும் எதிர்பார்ப்பீர்கள்.\n• பலன்: வசீகரம், ஆடம்பரம் மற்றும் சுகபோகமான வாழ்க்கையை விரும்புவீர்கள். நண்பர்களுடன் நேரத்தைச் செலவிடப் பிடிக்கும். அன்பால் எவரையும் கட்டிப்போடுவீர்கள்.\n• வழிபாடு: மகாலட்சுமி வழிபாடு உங்களுக்குச் செல்வச் செழிப்பை அள்ளித் தரும்.";
    }
    if (name.contains("சனி") || name.contains("saturday")) {
      return "சனிக்கிழமை (Saturday)\nஅதிபதி: சனி\n\n$intro • தன்மை: நீங்கள் உழைப்பிற்கும், பொறுமைக்கும் பெயர் பெற்றவர். எதார்த்தத்தை உணர்ந்து செயல்படுபவர்.\n• பலன்: நிதானமான வளர்ச்சி என்றாலும் அது நிலையானதாக இருக்கும். கடமை உணர்வு மிக்கவர். அனுபவத்தின் மூலம் வாழ்க்கைப் பாடங்களைக் கற்றுக் கொள்வீர்கள்.\n• வழிபாடு: ஆஞ்சநேயர் அல்லது சனி பகவானை வழிபட தடைகள் விலகி மேன்மை உண்டாகும்.";
    }

    return weekdayName;
  }

  static String getDetailedDasaPalan(String? lordName) {
    if (lordName == null) return "-";
    String name = lordName.toLowerCase();
    String intro = "நீங்கள் இப்போது $lordName தசையை அனுபவிக்கிறீர்கள்.\n\n";

    if (name.contains("சூரிய")) {
      return "$intro • தன்மை: அதிகாரம், கௌரவம் மற்றும் அரசு வழியில் நன்மைகள் கிடைக்கும் காலம்.\n• பலன்: சமூகத்தில் உங்களின் அந்தஸ்து உயரும். தந்தையாலும், தந்தை வழி உறவுகளாலும் ஆதாயம் உண்டாகும். நிர்வாகத் திறன் கூடும்.\n• கவனிக்க: அதிகப்படியான கோபம் மற்றும் உஷ்ணம் சம்பந்தப்பட்ட உடல்நல பாதிப்புகள் வரலாம்.";
    }
    if (name.contains("சந்திர")) {
      return "$intro • தன்மை: மன அமைதி, மகிழ்ச்சி மற்றும் வசதிகள் பெருகும் காலம்.\n• பலன்: வீடு மாற்றம் அல்லது ஊர் மாற்றம் ஏற்படலாம். தாயின் ஆதரவு முழுமையாகக் கிடைக்கும். கலை மற்றும் திரவப் பொருட்கள் மூலம் லாபம் வரும்.\n• கவனிக்க: மனநிலை தடுமாற்றம் மற்றும் சளி சம்பந்தப்பட்ட தொந்தரவுகள் வரலாம்.";
    }
    if (name.contains("செவ்வாய்")) {
      return "$intro • தன்மை: துணிச்சல், வேகம் மற்றும் சொத்து சேர்க்கைக்கான காலம்.\n• பலன்: நிலம், வீடு வாங்கும் யோகம் உண்டாகும். சகோதர வழியில் உதவிகள் கிடைக்கும். போட்டிகளில் வெற்றி பெறுவீர்கள்.\n• கவனிக்க: விபத்துக்கள் மற்றும் அறுவை சிகிச்சைகளில் எச்சரிக்கை தேவை. முன்கோபத்தைக் குறைக்கவும்.";
    }
    if (name.contains("ராகு")) {
      return "$intro • தன்மை: பிரம்மாண்டமான வளர்ச்சி அல்லது திடீர் திருப்பங்கள் நிறைந்த காலம்.\n• பலன்: வெளிநாடு செல்லும் யோகம், எதிர்பாராத பணவரவு மற்றும் அரசியல் செல்வாக்கு கிடைக்கும். புதிய தொழில்நுட்பத்தில் ஆர்வம் பிறக்கும்.\n• கவனிக்க: தேவையற்ற பயம் மற்றும் தவறான பழக்கவழக்கங்களில் சிக்காமல் இருப்பது அவசியம்.";
    }
    if (name.contains("குரு")) {
      return "$intro • தன்மை: பொற்காலம் என்று அழைக்கப்படும் ஞானமும் செல்வமும் சேரும் காலம்.\n• பலன்: திருமணம், புத்திர பாக்கியம் மற்றும் ஆன்மீகப் பயணங்கள் அமையும். கௌரவமான பதவி தேடி வரும். வங்கிச் சேமிப்பு உயரும்.\n• கவனிக்க: உடல் பருமன் மற்றும் கொழுப்புச் சத்து சார்ந்த ஆரோக்கியத்தில் கவனம் தேவை.";
    }
    if (name.contains("சனி")) {
      return "$intro • தன்மை: பொறுமையும், உழைப்பும் உங்கள் வாழ்க்கையைச் சீரமைக்கும் காலம்.\n• பலன்: ஆரம்பத்தில் சோதனைகள் இருந்தாலும், முடிவில் நிலையான சொத்துக்களையும் புகழையும் தரும். தொழில் வளர்ச்சி சீராக இருக்கும்.\n• கவனிக்க: சோம்பேறித்தனத்தைத் தவிர்ப்பதும், உழைப்பவர்களை மதிப்பபதும் அவசியம்.";
    }
    if (name.contains("புதன்")) {
      return "$intro • தன்மை: கல்வி, அறிவு மற்றும் வியாபாரத்தில் கொடிகட்டிப் பறக்கும் காலம்.\n• பலன்: பேச்சாற்றலால் சாதிப்பீர்கள். புதிய நண்பர்கள் கிடைப்பார்கள். கணக்கு மற்றும் தகவல் தொடர்பு துறையில் இருப்பவர்களுக்குப் பொற்காலம்.\n• கவனிக்க: நரம்புத் தளர்ச்சி மற்றும் தோலில் ஒவ்வாமை ஏற்படாமல் பார்த்துக்கொள்ளுங்கள்.";
    }
    if (name.contains("கேது")) {
      return "$intro • தன்மை: ஞானம், வைராக்கியம் மற்றும் ஆழமான சிந்தனைக்குரிய காலம்.\n• பலன்: ஆன்மீகத்தில் ஈடுபாடு அதிகரிக்கும். வெளிநாட்டுப் பயணங்கள் அமையலாம். தேவையற்ற செலவுகள் குறையும்.\n• கவனிக்க: மன உளைச்சல் மற்றும் மர்ம நோய்களில் எச்சரிக்கையாக இருக்க வேண்டும்.";
    }
    if (name.contains("சுக்கிர")) {
      return "$intro • தன்மை: சுகபோகங்கள், கலைகள் மற்றும் ஆடம்பர வாழ்வின் உச்சமான காலம்.\n• பலன்: வாகன யோகம், திருமண சுகம் மற்றும் ஆடை ஆபரணச் சேர்க்கை உண்டாகும். பெண்களால் அனுகூலம் கிடைக்கும்.\n• கவனிக்க: கண் கோளாறுகள் மற்றும் அளவுக்கு அதிகமான ஆசைகளால் வரும் பிரச்சனைகளைத் தவிர்க்கவும்.";
    }

    return lordName;
  }

  static String getDetailedBhuktiPalan(String? lordName) {
    if (lordName == null) return "-";
    String name = lordName.toLowerCase();
    String intro = "தற்போது நடக்கும் $lordName புத்தியின் விளைவுகள்:\n\n";

    if (name.contains("சூரிய")) return "$intro • அதிகாரம் மற்றும் கௌரவம் தேடி வரும். ஆனால் ஈகோ பிரச்சனைகள் வரலாம்.";
    if (name.contains("சந்திர")) return "$intro • மன நிம்மதி கிடைக்கும். நீர் தொடர்பான பயணங்கள் அமையலாம்.";
    if (name.contains("செவ்வாய்")) return "$intro • பூமி லாபம் கிடைக்கும். தையிரியமான முடிவுகள் எடுப்பீர்கள்.";
    if (name.contains("ராகு")) return "$intro • திடீர் லாபம் அல்லது தேவையற்ற அலைச்சல்கள் ஏற்படும். குழப்பங்கள் வரலாம்.";
    if (name.contains("குரு")) return "$intro • சுப காரியங்கள் நடக்கும். பெரியவர்களின் ஆசி கிட்டும்.";
    if (name.contains("சனி")) return "$intro • மெதுவான வளர்ச்சி, ஆனால் வேலையில் அதிக பொறுப்புகள் சேரும்.";
    if (name.contains("புதன்")) return "$intro • லாபம் மற்றும் அறிவுத்திறன் வெளிப்படும். நண்பர்களால் ஆதாயம்.";
    if (name.contains("கேது")) return "$intro • ஆன்மீக ஆர்வம் கூடும். சில நேரங்களில் தனிமையை உணர வைக்கும்.";
    if (name.contains("சுக்கிர")) return "$intro • ஆடம்பரப் பொருட்கள் வாங்குவீர்கள். மகிழ்ச்சியான சூழல் நிலவும்.";

    return lordName;
  }

  static String getDetailedYogaPalan(String? yogaName) {
    if (yogaName == null) return "-";
    
    String name = yogaName.toLowerCase();
    String intro = "நீங்கள் $yogaName யோகத்தில் பிறந்துள்ளீர்கள்.\n\n";

    if (name.contains("விஷ்கம்பம்") || name.contains("vishkambha")) {
      return "விஷ்கம்பம் (Vishkambha)\n\n$intro • தன்மை: நீங்கள் அழகான தோற்றமும், எதையும் தாங்கும் மனவலிமையும் கொண்டவர். மற்றவர்களின் செல்வாக்கைப் பெறுவீர்கள்.\n• பலன்: தனித்துச் செயல்பட்டு வெற்றி காண்பீர்கள். உங்கள் சொல்லிற்கு ஒரு தனி மதிப்பு இருக்கும்.";
    }
    if (name.contains("ப்ரீதி") || name.contains("preeti")) {
      return "ப்ரீதி (Preeti)\n\n$intro • தன்மை: நீங்கள் அன்பானவர்; அனைவரிடமும் இனிமையாகப் பழகுவீர்கள். கலைகளின் மீது ஆர்வம் அதிகம் இருக்கும்.\n• பலன்: மற்றவர்களின் அன்பால் உங்கள் காரியங்கள் எளிதில் நிறைவேறும். மகிழ்ச்சியான வாழ்க்கை அமெயும்.";
    }
    if (name.contains("ஆயுஷ்மான்") || name.contains("ayushman")) {
      return "ஆயுஷ்மான் (Ayushman)\n\n$intro • தன்மை: பெயருக்கேற்றார் போல நீங்கள் நீண்ட ஆயுளும், நல்ல ஆரோக்கியமும் கொண்டவர்.\n• பலன்: கல்வியில் சிறந்து விளங்குவீர்கள். உங்கள் உழைப்பால் செல்வத்தைச் சேர்ப்பீர்கள்.";
    }
    if (name.contains("சௌபாக்கியம்") || name.contains("saubhagya")) {
      return "சௌபாக்கியம் (Saubhagya)\n\n$intro • தன்மை: நீங்கள் மிகுந்த அதிர்ஷ்டசாலி. பார்ப்பதற்கே லட்சணமான முகம் கொண்டிருப்பீர்கள்.\n• பலன்: வாழ்நாள் முழுவதும் சுகபோகங்களை அனுபவிக்கும் யோகம் உங்களுக்கு உண்டு.";
    }
    if (name.contains("சோபனம்") || name.contains("shobhana")) {
      return "சோபனம் (Shobhana)\n\n$intro • தன்மை: நீங்கள் நற்குணங்கள் நிறைந்தவர். எப்போதும் மங்கலமான விஷயங்களில் ஆர்வம் காட்டுவீர்கள்.\n• பலன்: அறிவுத்திறன் மிக்கவர். குடும்பத்தில் எப்போதும் மகிழ்ச்சியை நிலைநாட்ட பாடுபடுவீர்கள்.";
    }
    if (name.contains("அதிகண்டம்") || name.contains("atiganda")) {
      return "அதிகண்டம் (Atiganda)\n\n$intro • தன்மை: நீங்கள் சவால்களைக் கண்டு அஞ்சாதவர். வாழ்க்கையில் பல தடைகளைத் தாண்டி முன்னேறுவீர்கள்.\n• பலன்: வீரமான செயல்களில் ஈடுபடுவீர்கள். கடின உழைப்பால் உயர்நிலையை அடைவீர்கள்.";
    }
    if (name.contains("சுகர்மம்") || name.contains("sukarma")) {
      return "சுகர்மம் (Sukarma)\n\n$intro • தன்மை: நீங்கள் தர்ம சிந்தனை கொண்டவர். நேர்மையான வழியில் முன்னேற விரும்புவீர்கள்.\n• பலன்: மற்றவர்களுக்கு உதவும் குணம் கொண்டவர். உங்கள் நற்செயல்களால் புகழ் பெறுவீர்கள்.";
    }
    if (name.contains("திருதி") || name.contains("dhriti")) {
      return "திருதி (Dhriti)\n\n$intro • தன்மை: நீங்கள் மிகுந்த பொறுமைசாலி. எதையும் நிதானமாக யோசித்துச் செயல்படுவீர்கள்.\n• பலன்: கல்வியிலும் செல்வத்திலும் சிறந்து விளங்குவீர்கள். எதற்கும் பதற்றப்பட மாட்டீர்கள்.";
    }
    if (name.contains("சூலம்") || name.contains("shoola")) {
      return "சூலம் (Shoola)\n\n$intro • தன்மை: நீங்கள் விவாதங்களில் வல்லவர். கோபம் வரும்போது சற்று எச்சரிக்கையாக இருக்க வேண்டும்.\n• பலன்: ஆன்மீகத்தில் ஈடுபாடு இருக்கும். உங்கள் கருத்துக்களைத் துணிச்சலாக முன்வைப்பீர்கள்.";
    }
    if (name.contains("கண்டம்") || name.contains("ganda")) {
      return "கண்டம் (Ganda)\n\n$intro • தன்மை: நீங்கள் விடாமுயற்சி கொண்டவர். பல சண்டைகளைச் சந்தித்து வெற்றி பெறுவீர்கள்.\n• பலன்: எதையும் தீர விசாரிக்கும் குணம் உண்டு. வாழ்க்கைப் பாடங்களை அனுபவத்தால் கற்றுக் கொள்வீர்கள்.";
    }
    if (name.contains("விருத்தி") || name.contains("vriddhi")) {
      return "விருத்தி (Vriddhi)\n\n$intro • தன்மை: உங்கள் வாழ்வில் படிப்படியான வளர்ச்சி எப்போதும் இருக்கும். புதிய விஷயங்களைக் கற்பதில் ஆர்வம் காட்டுவீர்கள்.\n• பலன்: வியாபாரம் மற்றும் கல்வியில் பெரும் வெற்றியும் லாபமும் கிடைக்கும்.";
    }
    if (name.contains("துருவம்") || name.contains("dhruva")) {
      return "துருவம் (Dhruva)\n\n$intro • தன்மை: நீங்கள் ஒரு ஸ்திரமான குணம் கொண்டவர். எடுத்த முடிவில் உறுதியாக இருப்பீர்கள்.\n• பலன்: சமூகத்தில் உங்களை ஒரு நம்பகமான மனிதராகப் பார்ப்பார்கள். நிலையான செல்வம் சேரும்.";
    }
    if (name.contains("வியாகாதம்") || name.contains("vyaghata")) {
      return "வியாகாதம் (Vyaghata)\n\n$intro • தன்மை: நீங்கள் துணிச்சலானவர். எதிரிகளை வீழ்த்தும் ஆற்றல் கொண்டவர்.\n• பலன்: கடினமான பணிகளையும் அநாயாசமாக முடிப்பீர்கள். உங்கள் ஆளுமை மற்றவர்களை வியக்க வைக்கும்.";
    }
    if (name.contains("ஹர்ஷணம்") || name.contains("harshana")) {
      return "ஹர்ஷணம் (Harshana)\n\n$intro • தன்மை: நீங்கள் எப்போதும் கலகலப்பாக இருப்பீர்கள். நகைச்சுவை உணர்வு உங்களுக்கு அதிகம்.\n• பலன்: அறிவாற்றல் மிக்கவர். உங்களைச் சுற்றியுள்ளவர்களை எப்போதும் உற்சாகமாக வைத்திருப்பீர்கள்.";
    }
    if (name.contains("வஜ்ரம்") || name.contains("vajra")) {
      return "வஜ்ரம் (Vajra)\n\n$intro • தன்மை: நீங்கள் வைரத்தைப் போன்ற உறுதி மிக்கவர். உங்கள் பேச்சில் ஒரு வேகம் இருக்கும்.\n• பலன்: உடல் பலம் மற்றும் மன பலம் கொண்டவர். செல்வச் செழிப்புடன் வாழ்வீர்கள்.";
    }
    if (name.contains("சித்தி") || name.contains("siddhi")) {
      return "சித்தி (Siddhi)\n\n$intro • தன்மை: நீங்கள் எதைச் செய்தாலும் அதில் முழுமை காண்பீர்கள். மற்றவர்களுக்கு வழிகாட்டியாகத் திகழ்வீர்கள்.\n• பலன்: பல கலைகளில் தேர்ச்சி பெறுவீர்கள். நீங்கள் நினைத்த காரியம் கைகூடும்.";
    }
    if (name.contains("வியதீபாதம்") || name.contains("vyatipata")) {
      return "வியதீபாதம் (Vyatipata)\n\n$intro • தன்மை: நீங்கள் மிகுந்த அறிவாற்றல் கொண்டவர். வாழ்க்கையின் ரகசியங்களைப் புரிந்து கொள்வீர்கள்.\n• பலன்: தத்துவ ஞானம் இருக்கும். மற்றவர்களுக்கு ஆலோசனைகள் வழங்கும் தகுதி உங்களுக்கு உண்டு.";
    }
    if (name.contains("வரியான்") || name.contains("variyan")) {
      return "வரியான் (Variyan)\n\n$intro • தன்மை: நீங்கள் ஆடம்பரத்தை விரும்புவீர்கள். வசதியான வாழ்க்கை வாழ வேண்டும் என்ற எண்ணம் கொண்டவர்.\n• பலன்: செல்வம் தேடி வரும். சமூகத்தில் கௌரவமான நிலையில் இருப்பீர்கள்.";
    }
    if (name.contains("பரிகம்") || name.contains("parigha")) {
      return "பரிகம் (Parigha)\n\n$intro • தன்மை: நீங்கள் நீதியையும் நேர்மையையும் விரும்புபவர். பல சாஸ்திரங்களைக் கற்றுத் தேர்ந்தவர்.\n• பலன்: எதற்கும் அஞ்சாமல் உண்மையைப் பேசுவீர்கள். பகைவர்களையும் நண்பர்களாக மாற்றும் திறன் உண்டு.";
    }
    if (name.contains("சிவம்") || name.contains("shiva")) {
      return "சிவம் (Shiva)\n\n$intro • தன்மை: நீங்கள் அமைதியான சுபாவம் கொண்டவர். தெய்வ பக்தி மற்றும் ஆன்மீகத்தில் ஈடுபாடு அதிகம்.\n• பலன்: மற்றவர்கள் மதிக்கக்கூடிய உயர்ந்த குணம் கொண்டவர். மன நிம்மதியுடன் வாழ்வீர்கள்.";
    }
    if (name.contains("சித்தம்") || name.contains("siddha")) {
      return "சித்தம் (Siddha)\n\n$intro • தன்மை: நீங்கள் எதையும் சாதிக்கும் ஆற்றல் கொண்டவர். மற்றவர்களுக்கு உதவும் நற்பண்பு இருக்கும்.\n• பலன்: தர்ம காரியங்களில் ஈடுபடுவீர்கள். உங்கள் வாழ்வில் புகழ் தானாகத் தேடி வரும்.";
    }
    if (name.contains("சாத்தியம்") || name.contains("sadhya")) {
      return "சாத்தியம் (Sadhya)\n\n$intro • தன்மை: நீங்கள் எந்த ஒரு காரியத்தையும் திறமையாகச் செய்து முடிப்பீர்கள். விடாமுயற்சி உங்கள் பலம்.\n• பலன்: நேர்மையான வழியில் பெரும் செல்வத்தைச் சேர்ப்பீர்கள்.";
    }
    if (name.contains("சுபம்") || name.contains("shubha")) {
      return "சுபம் (Shubha)\n\n$intro • தன்மை: நீங்கள் அழகான தோற்றமும், நல்ல ஒழுக்கமும் கொண்டவர். உங்கள் பேச்சு மற்றவர்களுக்கு இதமாக இருக்கும்.\n• பலன்: வாழ்நாள் முழுவதும் சுப காரியங்கள் உங்கள் இல்லத்தில் நிகழும்.";
    }
    if (name.contains("சுப்பிரம்") || name.contains("shukla")) {
      return "సుப்பிரம் (Shukla)\n\n$intro • தன்மை: நீங்கள் தூய்மையான மனம் கொண்டவர். ஒளிவுமறைவு இல்லாத குணம் உங்களுக்கு உண்டு.\n• பலன்: கல்வியில் சிறந்து விளங்குவீர்கள். அனைவரும் விரும்பத்தக்க மனிதராகத் திகழ்வீர்கள்.";
    }
    if (name.contains("பிரம்மம்") || name.contains("brahma")) {
      return "பிரம்மம் (Brahma)\n\n$intro • தன்மை: நீங்கள் மிகுந்த அறிவுத்திறன் மற்றும் விவேகம் கொண்டவர். ஆன்மீகப் பணிகளில் ஆர்வம் இருக்கும்.\n• பலன்: கௌரவம் மற்றும் செல்வாக்கு மிக்கவர். மற்றவர்களுக்கு ஒரு முன்னுதாரணமாக இருப்பீர்கள்.";
    }
    if (name.contains("ஐந்திரம்") || name.contains("aindra")) {
      return "ஐந்திரம் (Aindra)\n\n$intro • தன்மை: நீங்கள் அதிகாரமிக்க பதவிகளை வகிக்கும் தகுதி கொண்டவர். மற்றவர்களை வழிநடத்தும் ஆற்றல் உண்டு.\n• பலன்: புகழ் மற்றும் செல்வம் உங்களைத் தேடி வரும். அரச யோகம் அமையும்.";
    }
    if (name.contains("வைதிருதி") || name.contains("vaidhriti")) {
      return "வைதிருதி (Vaidhriti)\n\n$intro • தன்மை: நீங்கள் சகிப்புத்தன்மை மற்றும் மன உறுதி கொண்டவர். எதையும் பொறுமையுடன் கையாளுவீர்கள்.\n• பலன்: பல துறைகளில் அறிவு இருக்கும். உங்களின் தனித்துவமான செயல்களால் சாதனை படைப்பீர்கள்.";
    }

    return yogaName;
  }

  static String getDetailedKaranaPalan(String? karanaName) {
    if (karanaName == null) return "-";
    
    String name = karanaName.toLowerCase();
    String intro = "நீங்கள் $karanaName கரணத்தில் பிறந்துள்ளீர்கள்.\n\n";

    if (name.contains("பவ") || name.contains("bava")) {
      return "பவ கரணம் (Bava Karana)\n\n$intro • தன்மை: நீங்கள் எப்போதும் சுறுசுறுப்பாக இயங்கும் சுபாவம் கொண்டவர். எதையும் நேர்மறையாக அணுகுவீர்கள்.\n• செயல்பாடுகள்: உங்களின் கடின உழைப்பால் உயர்ந்த நிலையை அடைவீர்கள். ஆன்மீக காரியங்களில் ஆர்வம் இருக்கும்.\n• பலம்: மற்றவர்களுக்கு உதவும் நல்ல மனமும், விடாமுயற்சியும் உங்கள் பலம்.";
    }
    if (name.contains("பாலவ") || name.contains("balava")) {
      return "பாலவ கரணம் (Balava Karana)\n\n$intro • தன்மை: நீங்கள் மென்மையான இதயம் கொண்டவர். பார்ப்பதற்கு அமைதியாகத் தெரிந்தாலும் காரியத்தில் கண்ணாக இருப்பீர்கள்.\n• செயல்பாடுகள்: கலை, கல்வி மற்றும் எழுத்துத் துறையில் நீங்கள் பிரகாசிப்பீர்கள். பயணங்களை அதிகம் விரும்புவீர்கள்.\n• பலம்: வசீகரமான பேச்சும், மற்றவர்களை எளிதில் கவரும் ஆளுமையும் உங்களுக்கு உண்டு.";
    }
    if (name.contains("கௌலவ") || name.contains("kaulava")) {
      return "கௌலவ கரணம் (Kaulava Karana)\n\n$intro • தன்மை: நீங்கள் நட்பிற்கு அதிக முக்கியத்துவம் கொடுப்பவர். அனைவரிடமும் சமமாகப் பழகுவீர்கள்.\n• செயல்பாடுகள்: சமூக சேவைகளிலும், பொதுப் பணிகளிலும் ஈடுபட விரும்புவீர்கள். சுதந்திரமான செயல்பாடுகளை விரும்புபவர்.\n• பலம்: உங்களின் சுய கௌரவத்தை விட்டுக்கொடுக்காமல், வைராக்கியத்துடன் செயல்பட்டு வெற்றி பெறுவீர்கள்.";
    }
    if (name.contains("சைதில") || name.contains("taitila")) {
      return "சைதிலம் கரணம் (Taitila Karana)\n\n$intro • தன்மை: நீங்கள் அதிர்ஷ்டசாலியாகக் கருதப்படுவீர்கள். எதையும் எளிதாகப் பெற்றுவிடும் யோகம் உங்களுக்கு உண்டு.\n• செயல்பாடுகள்: அரசு சார்ந்த பணிகளிலும், நிர்வாகப் பொறுப்புகளிலும் சிறப்பாகச் செயல்படுவீர்கள்.\n• பலம்: உங்களின் பொறுமையும், அன்பான குணமும் உங்களைச் சுற்றியுள்ளவர்களை மகிழ்ச்சியாக வைத்திருக்கும்.";
    }
    if (name.contains("கரசை") || name.contains("garaja")) {
      return "கரசை கரணம் (Garaja Karana)\n\n$intro • தன்மை: நீங்கள் ஒரு எதார்த்தவாதி. நிலம், வீடு போன்ற அசையா சொத்துக்கள் மீது அதிக நாட்டம் இருக்கும்.\n• செயல்பாடுகள்: விவசாயம், கட்டுமானம் அல்லது இயந்திரங்கள் சார்ந்த துறைகளில் நீங்கள் வல்லவராக இருப்பீர்கள்.\n• பலம்: உங்களின் கடின உழைப்பே உங்களை ஒரு சிறந்த வெற்றியாளராக மாற்றும்.";
    }
    if (name.contains("வணிசை") || name.contains("vanija")) {
      return "வணிசை கரணம் (Vanija Karana)\n\n$intro • தன்மை: பெயருக்கேற்றார் போல, நீங்கள் வியாபாரத் தந்திரம் மிக்கவர். லாப நஷ்டங்களைச் சரியாகக் கணக்கிடுவீர்கள்.\n• செயல்பாடுகள்: வணிகம், வர்த்தகம் மற்றும் தகவல் தொடர்பு துறைகளில் பெரும் வெற்றி பெறுவீர்கள்.\n• பலம்: உங்களின் பேச்சுத் திறமையால் கடினமான காரியங்களையும் சுலபமாக முடித்துவிடுவீர்கள்.";
    }
    if (name.contains("பத்திரை") || name.contains("விஷ்டி") || name.contains("bhadra") || name.contains("vishti")) {
      return "பத்திரை கரணம் / விஷ்டி கரணம் (Bhadra / Vishti Karana)\n\n$intro • தன்மை: நீங்கள் மிகுந்த மன உறுதி கொண்டவர். சவால்களைக் கண்டு அஞ்ச மாட்டீர்கள்.\n• செயல்பாடுகள்: சட்டம், காவல் துறை அல்லது தடைகளைத் தகர்க்கும் கடினமான பணிகளில் நீங்கள் சிறப்பாகச் செயல்படுவீர்கள்.\n• பலம்: உங்கள் உள்ளுணர்வு மிக வலுவானது. எதையும் முன்கூட்டியே கணிக்கும் திறன் உங்களுக்கு உண்டு.";
    }
    if (name.contains("சகுனி") || name.contains("shakuni")) {
      return "சகுனி கரணம் (Shakuni Karana)\n\n$intro • தன்மை: நீங்கள் மிகுந்த அறிவுத்திறன் மற்றும் தந்திரம் மிக்கவர். மருந்து மற்றும் மந்திரத் துறைகளில் ஆர்வம் இருக்கலாம்.\n• செயல்பாடுகள்: பிரச்சனைகளைத் தீர்ப்பவதில் நீங்கள் வல்லவர். ஒரு சிறந்த ஆலோசகராகத் திகழ்வீர்கள்.\n• பலம்: கூர்மையான புத்தியும், எதையும் ஆராய்ந்து முடிவெடுக்கும் குணமும் உங்கள் சிறப்பு.";
    }
    if (name.contains("சதுஷ்பாத") || name.contains("chatushpada")) {
      return "சதுஷ்பாத கரணம் (Chatushpada Karana)\n\n$intro • தன்மை: நீங்கள் விலங்குகள் மற்றும் இயற்கையின் மீது அதிக அன்பு கொண்டவர். பெரியோர்களை மதிக்கும் பண்பு கொண்டவர்.\n• செயல்பாடுகள்: கால்நடை வளர்ப்பு, விவசாயம் அல்லது அரசாங்க கௌரவப் பதவிகளில் நீங்கள் ஜொலிப்பீர்கள்.\n• பலம்: உங்களின் நேர்மையும், தர்மம் தவறாத குணமுமே உங்களைக் காக்கும்.";
    }
    if (name.contains("நாகவ") || name.contains("nagava")) {
      return "நாகவ கரணம் (Nagava Karana)\n\n$intro • தன்மை: நீங்கள் எதையும் மறைமுகமாகச் சாதிக்கும் திறன் கொண்டவர். நிலத்தடி வளங்கள் பற்றிய அறிவு இருக்கும்.\n• செயல்பாடுகள்: சுரங்கம், ரசாயனம் அல்லது ஆராய்ச்சித் துறைகளில் நீங்கள் பெரிய வெற்றியைப் பெறுவீர்கள்.\n• பலம்: தோல்விகளைக் கண்டு அஞ்சாமல், அடுத்தடுத்த திட்டங்களை வகுப்பதில் நீங்கள் கில்லாடி.";
    }
    if (name.contains("கிமிஸ்து") || name.contains("kimstughna")) {
      return "கிமிஸ்துக்கினம் கரணம் (Kimstughna Karana)\n\n$intro • தன்மை: நீங்கள் மிகுந்த அதிர்ஷ்டசாலி. எப்போதும் மகிழ்ச்சியாக இருக்க விரும்புவீர்கள்.\n• செயல்பாடுகள்: மங்கல காரியங்களை முன்னின்று நடத்துவீர்கள். கல்வி மற்றும் போதனைத் துறைகளில் சிறந்து விளங்குவீர்கள்.\n• பலம்: உங்களின் தூய்மையான எண்ணங்களும், இறை நம்பிக்கையும் உங்களை எப்போதும் பாதுகாக்கும்.";
    }

    return karanaName;
  }

  static String getDetailedThithiPalan(String? thithiName) {
    if (thithiName == null) return "-";
    
    String name = thithiName.toLowerCase();
    String intro = "நீங்கள் $thithiName திதியில் பிறந்துள்ளீர்கள்.\n\n";

    if (name.contains("பௌர்ணமி") || name.contains("pournami")) {
      return "பௌர்ணமி (Full Moon)\n\n$intro நீங்கள் முழுமையான மனநிறைவும், அழகும், வசீகரமும் கொண்டவர். சமூகத்தில் உயர்ந்த அந்தஸ்தைப் பெறுவீர்கள்.\n\n• வழிபாடு: அம்பிகையை (அம்மன்) வழிபட சகல சௌபாக்கியங்களும் கிடைக்கும்.";
    }
    if (name.contains("அமாவாசை") || name.contains("amavasya")) {
      return "அமாவாசை (New Moon)\n\n$intro நீங்கள் ஆழ்ந்த சிந்தனை மற்றும் ரகசியங்களைக் கையாளும் திறன் கொண்டவர். முன்னோர்களின் ஆசி உங்களுக்கு எப்போதும் உண்டு.\n\n• வழிபாடு: பித்ருக்களை (முன்னோர்கள்) வழிபட வம்சம் விருத்தியாகும்.";
    }

    if (name.contains("பிரதமை") || name.contains("prathami")) {
      return "பிரதமை (Prathami)\n\n$intro • தன்மை: நீங்கள் எதையும் சுயமாகத் தொடங்க விரும்பும் ஆற்றல் கொண்டவர். புதிய முயற்சிகளில் அதிக ஆர்வம் இருக்கும்.\n• பலம்: தலைமைப் பண்பு மற்றும் எதற்கும் அஞ்சாத குணம்.\n• வழிபாடு: அக்னி தேவனையும், சிவபெருமானையும் வழிபட வெற்றிகள் குவியும்.";
    }
    if (name.contains("துவிதியை") || name.contains("dwitiya")) {
      return "துவிதியை (Dwitiya)\n\n$intro • தன்மை: நீங்கள் மற்றவர்களுடன் இணைந்து செயல்படுவதில் வல்லவர். சிறந்த பேச்சாற்றல் கொண்டிருப்பீர்கள்.\n• பலம்: அரசாங்க வழியில் ஆதாயம் மற்றும் பயணங்களால் நன்மைகள் கிடைக்கும்.\n• வழிபாடு: பிரம்ம தேவனை வணங்குவது உங்கள் படைப்பாற்றலை வளர்க்கும்.";
    }
    if (name.contains("திருதியை") || name.contains("tritiya")) {
      return "திருதியை (Tritiya)\n\n$intro • தன்மை: நீங்கள் எதிலும் மகிழ்ச்சியையும், அழகையும் தேடுபவர். கலைகளில் மிகுந்த ஈடுபாடு இருக்கும்.\n• பலம்: செல்வம் சேர்ப்பதில் ஆர்வம் மற்றும் குடும்பத்தின் மீது அதிக பற்று.\n• வழிபாடு: கௌரி தேவியை (அம்மன்) வழிபட மங்கலங்கள் உண்டாகும்.";
    }
    if (name.contains("சதுர்த்தி") || name.contains("chaturthi")) {
      return "சதுர்த்தி (Chaturthi)\n\n$intro • தன்மை: நீங்கள் மிகுந்த விடாமுயற்சி கொண்டவர். தடைகளைத் தகர்த்து முன்னேறுவதில் வல்லவர்.\n• பலம்: எதையும் நுணுக்கமாகக் கவனிக்கும் திறன் மற்றும் ரகசியங்களைக் காக்கும் குணம்.\n• வழிபாடு: விநாயகப் பெருமானை வணங்கினால் உங்கள் தடைகள் அனைத்தும் விலகும்.";
    }
    if (name.contains("பஞ்சமி") || name.contains("panchami")) {
      return "பஞ்சமி (Panchami)\n\n$intro • தன்மை: நீங்கள் அறிவாற்றல் மற்றும் உயர்ந்த சிந்தனைகள் கொண்டவர். சமூகத்தில் நல்ல மதிப்பைப் பெறுவீர்கள்.\n• பலம்: மற்றவர்களுக்கு ஆலோசனை கூறும் தகுதி மற்றும் தாராள குணம்.\n• வழிபாடு: நாகராஜர் அல்லது சரஸ்வதி தேவியை வழிபட ஞானம் பெருகும்.";
    }
    if (name.contains("சஷ்டி") || name.contains("shashti")) {
      return "சஷ்டி (Shashti)\n\n$intro • தன்மை: நீங்கள் நீதியையும் நேர்மையையும் விரும்புபவர். நண்பர்களுக்காக எதையும் செய்யத் துணிவீர்கள்.\n• பலம்: புகழ், செல்வாக்கு மற்றும் எதிரிகளை வெல்லும் ஆற்றல்.\n• வழிபாடு: முருகப் பெருமானை வழிபட அனைத்துக் காரியங்களிலும் வெற்றி கிடைக்கும்.";
    }
    if (name.contains("சப்தமி") || name.contains("saptami")) {
      return "சப்தமி (Saptami)\n\n$intro • தன்மை: நீங்கள் எதிலும் நேர்த்தியையும் ஒழுக்கத்தையும் எதிர்பார்ப்பவர். தொலைநோக்கு பார்வை கொண்டவர்.\n• பலம்: அரசு வேலை மற்றும் கௌரவமான பதவிகள் தேடி வரும்.\n• வழிபாடு: சூரிய பகவானை வணங்குவது உங்கள் ஆரோக்கியத்தையும் புகழையும் கூட்டும்.";
    }
    if (name.contains("அஷ்டமி") || name.contains("ashtami")) {
      return "அஷ்டமி (Ashtami)\n\n$intro • தன்மை: நீங்கள் எதையும் தைரியமாக எதிர்கொள்ளும் மன உறுதி கொண்டவர். சவால்கள் உங்களை வளர்க்கும்.\n• பலம்: கடின உழைப்பு மற்றும் நீதியை நிலைநாட்டும் குணம்.\n• வழிபாடு: பத்ரகாளி அல்லது பைரவரை வழிபட பயம் நீங்கி வெற்றி உண்டாகும்.";
    }
    if (name.contains("நவமி") || name.contains("navami")) {
      return "நவமி (Navami)\n\n$intro • தன்மை: நீங்கள் மிகவும் சகிப்புத்தன்மை கொண்டவர். போராட்டங்களுக்குப் பின் பெரிய வெற்றியைப் பெறுவீர்கள்.\n• பலம்: எதையும் தாங்கும் இதயம் மற்றும் சிறந்த நிர்வாகத் திறன்.\n• வழிபாடு: ஸ்ரீராமச்சந்திர மூர்த்தி அல்லது துர்க்கை அம்மனை வழிபட நன்மைகள் பெருகும்.";
    }
    if (name.contains("தசமி") || name.contains("dashami")) {
      return "தசமி (Dashami)\n\n$intro • தன்மை: நீங்கள் தர்மம் மற்றும் ஒழுக்கத்தைக் கடைபிடிப்பவர். அனைவரிடமும் அன்பாகப் பழகுவீர்கள்.\n• பலம்: நிலையான செல்வம், புகழ் மற்றும் மகிழ்ச்சியான வாழ்க்கை.\n• வழிபாடு: எம தர்மராஜன் (அல்லது தர்ம தேவதை) வழிபாடு உங்கள் ஆயுளையும் ஆரோக்கியத்தையும் காக்கும்.";
    }
    if (name.contains("ஏகாதசி") || name.contains("ekadashi")) {
      return "ஏகாதசி (Ekadashi)\n\n$intro • தன்மை: நீங்கள் ஆன்மீகச் சிந்தனை மற்றும் தூய்மையான உள்ளம் கொண்டவர். விரதங்களின் மகிமையை உணர்ந்தவர்.\n• பலம்: வாக்குச் சுத்தம் மற்றும் மற்றவர்களுக்கு உதவும் நல்ல குணம்.\n• வழிபாடு: மகாவிஷ்ணுவை வழிபட அஷ்ட ஐஸ்வர்யங்களும் கிட்டும்.";
    }
    if (name.contains("துவாதசி") || name.contains("dwadashi")) {
      return "துவாதசி (Dwadashi)\n\n$intro • தன்மை: நீங்கள் தான தர்மங்கள் செய்வதில் ஆர்வம் கொண்டவர். பிறருக்கு வழிகாட்டியாகத் திகழ்வீர்கள்.\n• பலம்: வெளிநாடு செல்லும் யோகம் மற்றும் நீர்நிலை சார்ந்த நன்மைகள்.\n• வழிபாடு: விஷ்ணு பகவானை மதுசூதனனாக வழிபட மோட்சமும் நற்பலன்களும் கிடைக்கும்.";
    }
    if (name.contains("திரயோதசி") || name.contains("trayodashi")) {
      return "திரயோதசி (Trayodashi)\n\n$intro • தன்மை: நீங்கள் அறிவுக்கூர்மையும், நீண்ட ஆயுளும் கொண்டவர். எதையும் எளிதில் கிரகிக் கொள்வீர்கள்.\n• பலம்: சிறந்த கல்வி மற்றும் குடும்பத்தில் மகிழ்ச்சி நிலவும்.\n• வழிபாடு: சிவபெருமானை பிரதோஷ காலத்தில் வழிபடுவது பெரும் புண்ணியத்தைத் தரும்.";
    }
    if (name.contains("சதுர்த்தசி") || name.contains("chaturdashi")) {
      return "சதுர்த்தசி (Chaturdashi)\n\n$intro • தன்மை: நீங்கள் தைரியமான முடிவுகளை எடுப்பவர். சவாலான பணிகளில் ஈடுபட விரும்புவீர்கள்.\n• பலம்: அதீத ஆற்றல் மற்றும் கடினமான சூழல்களைக் கையாளும் திறன்.\n• வழிபாடு: ருத்ரன் அல்லது பைரவரை வழிபட இன்னல்கள் அகலும்.";
    }

    return thithiName;
  }

  static String getDetailedRasiPalan(String? rasiKey) {
    if (rasiKey == null) return "-";
    switch (rasiKey) {
      case 'Aries':
        return "மேஷ ராசி (Aries) - அசுவினி, பரணி, கார்த்திகை 1-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் மேஷ ராசியில் பிறந்துள்ளீர்கள். சர ராசியும் நெருப்பு தத்துவமும் கொண்ட நீங்கள், எதற்கும் அஞ்சாத போர்வீரனைப் போன்றவர்.\n\n• அடிப்படை குணம்: வேகம், விவேகம் மற்றும் தலைமைப் பண்பு உங்கள் அடையாளம். எதையும் யோசிப்பதை விடச் செய்வதிலேயே ஆர்வம் காட்டுவீர்கள்.\n• தொழில் & வெற்றி: நிர்வாகம், அதிகாரம் மிக்க பதவிகள் உங்களுக்குப் பொருந்தும். போட்டிகளில் வெற்றி பெறுவதே உங்கள் லட்சியம்.\n• சவால் & தீர்வு: அவசரப்பட்டு முடிவெடுப்பதைத் தவிர்த்து, பொறுமையைக் கையாண்டால் நீங்கள் தொடாத சிகரமே இல்லை.\n• வழிபாடு: முருகப்பெருமானை வணங்குவது உங்கள் ஆற்றலைச் சரியான திசையில் செலுத்தும்.";
      case 'Taurus':
        return "ரிஷப ராசி (Taurus) - கார்த்திகை 2, 3, 4, ரோகிணி, மிருகசீரிஷம் 1, 2-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் ரிஷப ராசியில் பிறந்துள்ளீர்கள். நிலத் தத்துவமும் ஸ்திரத் தன்மையும் கொண்ட நீங்கள், நம்பகத்தன்மைக்கு மறுபெயர்.\n\n• அடிப்படை குணம்: பொறுமை, நிதானம் மற்றும் கலை ரசனை மிக்கவர். ஆடம்பரத்தையும் தரமான வாழ்க்கையையும் விரும்புவீர்கள்.\n• தொழில் & வெற்றி: நிதி மேலாண்மை, கலைத்துறை மற்றும் உணவு சார்ந்த தொழில்களில் நீங்கள் பெரிய லாபம் ஈட்டுவீர்கள்.\n• சவால் & தீர்வு: அதீத பிடிவாதத்தைக் குறைத்துக் கொண்டு காலத்திற்கு ஏற்ப மாறினால் உங்கள் வளர்ச்சி வேகம் எடுக்கும்.\n• வழிபாடு: மகாலட்சுமி வழிபாடு உங்களுக்குச் செல்வச் செழிப்பை அள்ளித் தரும்.";
      case 'Gemini':
        return "மிதுன ராசி (Gemini) - மிருகசீரிஷம் 3, 4, திருவாதிரை, புனர்பூசம் 1, 2, 3-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் மிதுன ராசியில் பிறந்துள்ளீர்கள். காற்று தத்துவமும் உபய தன்மையும் கொண்ட நீங்கள், அறிவாற்றலில் சிறந்தவர்.\n\n• அடிப்படை குணம்: சிறந்த பேச்சாற்றல், நகைச்சுவை உணர்வு மற்றும் எதையும் எளிதில் கற்றுக் கொள்ளும் திறன் உங்களுக்கு உண்டு.\n• தொழில் & வெற்றி: தகவல் தொடர்பு, எழுத்து, கணிதம் மற்றும் தரகு சார்ந்த தொழில்கள் உங்களுக்கு வெற்றியைத் தேடித்தரும்.\n• சவால் & தீர்வு: இரட்டை மனநிலையைத் தவிர்த்து, ஒரு காரியத்தில் முழுமையாகக் கவனம் செலுத்தினால் சாதிக்கலாம்.\n• வழிபாடு: மகாவிஷ்ணுவை வழிபடுவது உங்கள் புத்திசாலித்தனத்தை மேன்மையடையச் செய்யும்.";
      case 'Cancer':
        return "கடக ராசி (Cancer) - புனர்பூசம் 4, பூசம், ஆயில்யம்\n\nவாழ்த்துகள்! நீங்கள் கடக ராசியில் பிறந்துள்ளீர்கள். நீர் தத்துவத்தைக் கொண்ட நீங்கள், ஈரமான இதயம் கொண்டவர்கள்.\n\n• அடிப்படை குணம்: தாயன்பு, கற்பனை வளம் மற்றும் நினைவாற்றல் மிக்கவர். குடும்பத்தின் மீது அதீத பற்று கொண்டிருப்பீர்கள்.\n• தொழில் & வெற்றி: பொதுச் சேவை, ஹோட்டல் துறை, ஆபரணத் தொழில் மற்றும் கல்விப் பணிகளில் நீங்கள் சிறந்து விளங்குவீர்கள்.\n• சவால் & தீர்வு: உணர்ச்சிவசப்படுவதைக் குறைத்துக் கொண்டு எதார்த்தமாகச் சிந்தித்தால் மன அமைதி கிடைக்கும்.\n• வழிபாடு: பார்வதி தேவி அல்லது பௌர்ணமி நிலவை வழிபடுவது உங்கள் மனதை உறுதிப்படுத்தும்.";
      case 'Leo':
        return "சிம்ம ராசி (Leo) - மகம், பூரம், உத்திரம் 1-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் சிம்ம ராசியில் பிறந்துள்ளீர்கள். நெருப்பு தத்துவமும் சூரியனின் ஆதிக்கமும் கொண்ட நீங்கள், அரசாட்சி செய்யப் பிறந்தவர்.\n\n• அடிப்படை குணம்: கம்பீரம், தாராள குணம் மற்றும் நேர்மை உங்கள் பலம். யாருக்கும் பயப்படாமல் உண்மையை உரக்கச் சொல்வீர்கள்.\n• தொழில் & வெற்றி: அரசியல், நிர்வாகம், தலைமைப் பொறுப்புகள் மற்றும் அரசு ஒப்பந்தங்கள் உங்களுக்கு யோகத்தைத் தரும்.\n• சவால் & தீர்வு: அதீத கௌரவம் பார்ப்பதைத் தவிர்த்து, மற்றவர்களின் ஆலோசனைகளுக்கும் மதிப்பு கொடுப்பது நல்லது.\n• வழிபாடு: சூரிய பகவானை வணங்குவதும் ஆதித்ய ஹிருதயம் படிப்பதும் பெரும் புகழைத் தரும்.";
      case 'Virgo':
        return "கன்னி ராசி (Virgo) - உத்திரம் 2, 3, 4, அஸ்தம், சித்திரை 1, 2-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் கன்னி ராசியில் பிறந்துள்ளீர்கள். நிலத் தத்துவமும் புதனின் ஆதிக்கமும் கொண்ட நீங்கள், நேர்த்தியின் சிகரம்.\n\n• அடிப்படை குணம்: எதையும் நுணுக்கமாக ஆராயும் திறன், தூய்மை மற்றும் புத்திசாலித்தனம் மிக்கவர். விமர்சனங்களை ரசிப்பீர்கள்.\n• தொழில் & வெற்றி: கணக்கியல், மருத்துவம், சட்டம் மற்றும் தொழில்நுட்பத் துறைகளில் நீங்கள் சாதனையாளராகத் திகழ்வீர்கள்.\n• சவால் & தீர்வு: தேவையற்ற கவலைகளை விடுத்து, செயலில் மட்டும் கவனம் செலுத்தினால் வெற்றி நிச்சயம்.\n• வழிபாடு: ஸ்ரீ ஹயக்ரீவர் வழிபாடு உங்கள் கல்வி மற்றும் தொழில் அறிவை வளர்க்கும்.";
      case 'Libra':
        return "துலாம் ராசி (Libra) - சித்திரை 3, 4, சுவாதி, விசாகம் 1, 2, 3-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் துலாம் ராசியில் பிறந்துள்ளீர்கள். காற்று தத்துவமும் தராசு சின்னமும் கொண்ட நீங்கள், உலகத்தைச் சமமாகப் பார்ப்பவர்.\n\n• அடிப்படை குணம்: நீதி, நேர்மை மற்றும் சமரசம் செய்து வைக்கும் குணம் கொண்டவர். கலைகளின் மீது மிகுந்த ஆர்வம் இருக்கும்.\n• தொழில் & வெற்றி: சட்டம், கலைத்துறை, அரசியல் மற்றும் வியாபாரத்தில் நீங்கள் நல்ல லாபம் காண்பீர்கள்.\n• சவால் & தீர்வு: அடுத்தவர்களின் முகஸ்துதியை நம்பி ஏமாறாமல், சுயமாகச் சிந்தித்து முடிவெடுக்கப் பழகுங்கள்.\n• வழிபாடு: ஆடல்வல்லான் சிவபெருமானை வணங்குவது உங்கள் வாழ்வில் இசைவையும் அமைதியையும் தரும்.";
      case 'Scorpio':
        return "விருச்சிக ராசி (Scorpio) - விசாகம் 4, அனுஷம், கேட்டை\n\nவாழ்த்துகள்! நீங்கள் விருச்சிக ராசியில் பிறந்துள்ளீர்கள். நீர் தத்துவமும் செவ்வாயின் ஆதிக்கமும் கொண்ட நீங்கள், ஆழமான சிந்தனையாளர்.\n\n• அடிப்படை குணம்: மன உறுதி, ரகசியங்களைக் காத்தல் மற்றும் எதிரிகளை வீழ்த்தும் வீரம் கொண்டவர். உங்கள் உள்ளுணர்வு மிகத் துல்லியமானது.\n• தொழில் & வெற்றி: ஆராய்ச்சி, காவல் துறை, ஆன்மீகம் மற்றும் மருத்துவம் போன்ற துறைகளில் நீங்கள் நிபுணராக இருப்பீர்கள்.\n• சவால் & தீர்வு: மனதில் வன்மம் வைக்காமல் எதையும் மன்னிக்கும் பழக்கத்தை வளர்த்துக் கொண்டால் உயர்வு உண்டு.\n• வழிபாடு: வராகி அம்மன் அல்லது நரசிம்மர் வழிபாடு உங்களுக்குப் பாதுகாப்பும் வெற்றையும் தரும்.";
      case 'Sagittarius':
        return "தனுசு ராசி (Sagittarius) - மூலம், பூராடம், உத்திராடம் 1-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் தனுசு ராசியில் பிறந்துள்ளீர்கள். நெருப்பு தத்துவமும் குருவின் ஆதிக்கமும் கொண்ட நீங்கள், லட்சியவாதி.\n\n• அடிப்படை குணம்: நேர்மை, உயர்ந்த சிந்தனை மற்றும் பயணம் செய்வதில் ஆர்வம் கொண்டவர். பிறருக்கு வழிகாட்டும் ஆசானாகத் திகழ்வீர்கள்.\n• தொழில் & வெற்றி: ஆன்மீகம், வங்கி, சட்டம் மற்றும் உயர் கல்வி நிறுவனங்களில் நீங்கள் பெரிய அந்தஸ்தைப் பெறுவீர்கள்.\n• சவால் & தீர்வு: யதார்த்தத்தை மீறிய வாக்குறுதிகளைக் கொடுப்பதைத் தவிர்த்தால் உங்கள் கௌரவம் நிலைக்கும்.\n• வழிபாடு: தட்சிணாமூர்த்தியை வணங்குவது உங்கள் ஞானத்தையும் செல்வத்தையும் பெருக்கும்.";
      case 'Capricorn':
        return "மகர ராசி (Capricorn) - உத்திராடம் 2, 3, 4, திருவோணம், அவிட்டம் 1, 2-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் மகர ராசியில் பிறந்துள்ளீர்கள். நிலத் தத்துவமும் சனியின் ஆதிக்கமும் கொண்ட நீங்கள், உழைப்பின் உறைவிடம்.\n\n• அடிப்படை குணம்: விடாமுயற்சி, பொறுமை மற்றும் கடமை தவறாத குணம் கொண்டவர். உங்கள் வளர்ச்சி நிதானமாக இருந்தாலும் நிலையாக இருக்கும்.\n• தொழில் & வெற்றி: கட்டுமானம், இயந்திரங்கள், விவசாயம் மற்றும் பழைய பொருட்கள் சார்ந்த தொழில்கள் உங்களுக்கு ஏற்றவை.\n• சவால் & தீர்வு: அதிகப்படியான இறுக்கத்தைக் குறைத்துக்கொண்டு மற்றவர்களுடன் கனிவாகப் பழகினால் மன அழுத்தம் குறையும்.\n• வழிபாடு: ஐயப்ப சுவாமி அல்லது விநாயகரை வணங்குவது தடைகளைத் தகர்க்கும்.";
      case 'Aquarius':
        return "கும்ப ராசி (Aquarius) - அவிட்டம் 3, 4, சதயம், பூரட்டாதி 1, 2, 3-ஆம் பாதம்\n\nவாழ்த்துகள்! நீங்கள் கும்ப ராசியில் பிறந்துள்ளீர்கள். காற்று தத்துவமும் சனியின் ஆதிக்கமும் கொண்ட நீங்கள், புதுமை விரும்பி.\n\n• அடிப்படை குணம்: மனிதாபிமானம், சமூகச் சிந்தனை மற்றும் அறிவியல்பூர்வமான பார்வை கொண்டவர். நீங்கள் ஒரு தனித்துவமான மனிதர்.\n• தொழில் & வெற்றி: நவீனத் தொழில்நுட்பம், கண்டுபிடிப்புகள், சோதிடம் மற்றும் சமூக நலப் பணிகள் உங்களுக்குச் சிறந்தது.\n• சவால் & தீர்வு: தனிமையை விரும்புவததைத் தவிர்த்து, சமூகத்தோடு இணைந்து செயல்பட்டால் உங்கள் லட்சியம் நிறைவேறும்.\n• வழிபாடு: காலபைரவர் வழிபாடு உங்கள் பயத்தைப் போக்கித் துணிவைத் தரும்.";
      case 'Pisces':
        return "மீன ராசி (Pisces) - பூரட்டாதி 4, உத்திரட்டாதி, ரேவதி\n\nவாழ்த்துகள்! நீங்கள் மீன ராசியில் பிறந்துள்ளீர்கள். நீர் தத்துவமும் குருவின் ஆதிக்கமும் கொண்ட நீங்கள், ஞானத்தின் இருப்பிடம்.\n\n• அடிப்படை குணம்: இரக்க குணம், தியாக மனப்பான்மை மற்றும் கற்பனை வளம் மிக்கவர். அனைவரையும் நேசிக்கும் பண்பு கொண்டவர்.\n• தொழில் & வெற்றி: கடல் சார்ந்த தொழில்கள், இசை, ஓவியம், எழுத்து மற்றும் ஆன்மீகப் பணிகளில் நீங்கள் புகழடைவீர்கள்.\n• சவால் & தீர்வு: பகல் கனவு காண்பதைத் தவிர்த்து, செயலில் இறங்கினால் உங்கள் கனவுகள் நனவாகும்.\n• வழிபாடு: திருச்செந்தூர் முருகன் அல்லது ராகவேந்திரர் வழிபாடு உங்களுக்குப் பெரும் நிம்மதியைத் தரும்.";
      default:
        return "${KPService.TAMIL_SIGNS[rasiKey] ?? rasiKey} ராசி";
    }
  }

  static String getDetailedNakshatraPalan(String? nakshatraName, int? pada) {
    if (nakshatraName == null) return "-";
    // We use the index to be safe against spelling variations in different data sources
    int index = KPService.NAKSHATRAS.indexOf(nakshatraName);
    if (index == -1) return "$nakshatraName (${pada ?? '-'} ஆம் பாதம்)";

    String padaText = pada != null ? "$pada-ஆம் பாதம்" : "";

    switch (index) {
      case 0: // அசுவனி
        return "அசுவினி (Ashwini) $padaText\n\nவாழ்த்துகள்! நீங்கள் அசுவினி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். தேவ மருத்துவர்களான அசுவினி தேவர்களை அதிபதியாகக் கொண்ட நீங்கள், எதிலும் வேகமானவர்.\n\n• தன்மை: சுறுசுறுப்பு உங்கள் அடையாளம். ஒரு செயலைத் தொடங்கினால் அதை மின்னல் வேகத்தில் முடிப்பீர்கள்.\n• பரிகாரம்: விநாயகப் பெருமானை வழிபட வெற்றிகள் குவியும்.";
      case 1: // பரணி
        return "பரணி (Bharani) $padaText\n\nவாழ்த்துகள்! நீங்கள் பரணி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். \"பரணியில் பிறந்தவர் தரணி ஆள்வார்\" என்பதற்கேற்ப, நீங்கள் ஆளுமைத் திறன் மிக்கவர்.\n\n• தன்மை: உண்மையை நேசிப்பவர், அஞ்சாத குணம் கொண்டவர். கலைகளில் ஆர்வம் அதிகம் இருக்கும்.\n• பரிகாரம்: துர்க்கை அம்மனை வழிபட தடைகள் நீங்கும்.";
      case 2: // கிருத்திகை
        return "கார்த்திகை (Krithika) $padaText\n\nவாழ்த்துகள்! நீங்கள் கார்த்திகை நட்சத்திரத்தில் பிறந்துள்ளீர்கள். அக்னி தேவனையும் சூரியனையும் ஆதிக்கமாகக் கொண்ட நீங்கள், பிரகாசமானவர்.\n\n• தன்மை: கூர்மையான அறிவு, கண்டிப்பான சுபாவம். பிறருக்கு வழிகாட்டும் தலைமைப் பண்பு கொண்டவர்.\n• பரிகாரம்: செவ்வாய்க்கிழமை தோறும் முருகனை வழிபட வாழ்வு சிறக்கும்.";
      case 3: // ரோகிணி
        return "ரோகிணி (Rohini) $padaText\n\nவாழ்த்துகள்! நீங்கள் ரோகிணி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். சந்திரனின் முழு அன்பைப் பெற்ற நீங்கள், வசீகரமான தோற்றம் கொண்டவர்.\n\n• தன்மை: கற்பனை வளம், மென்மையான பேச்சு மற்றும் கலை உணர்வு மிக்கவர். அனைவரையும் ஈர்க்கும் குணம் உண்டு.\n• பரிகாரம்: கிருஷ்ணரை வழிபட மன அமைதியும் மகிழ்ச்சியும் பெருகும்.";
      case 4: // மிருகசீர்ஷம்
        return "மிருகசீரிஷம் (Mrigashira) $padaText\n\nவாழ்த்துகள்! நீங்கள் மிருகசீரிஷம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். தேடுதல் குணம் கொண்ட நீங்கள், எதையும் துருவித் துருவி ஆராய்ந்து அறிவதில் வல்லவர்.\n\n• தன்மை: அமைதியானவர், ஆனால் காரியத்தில் கண்ணாக இருப்பவர். பயணங்களை அதிகம் விரும்புவீர்கள்.\n• பரிகாரம்: சிவபெருமானை வழிபட வாழ்வில் தெளிவு பிறக்கும்.";
      case 5: // திருவாதிரை
        return "திருவாதிரை (Ardra) $padaText\n\nவாழ்த்துகள்! நீங்கள் திருவாதிரை நட்சத்திரத்தில் பிறந்துள்ளீர்கள். ருத்ரனின் அம்சமான நீங்கள், அறிவாற்றலும் மாற்றங்களை உருவாக்கும் திறனும் கொண்டவர்.\n\n• தன்மை: எதார்த்தவாதி. கஷ்டங்களைத் தாங்கும் மன உறுதி கொண்டவர். ஆராய்ச்சி மனப்பான்மை அதிகம்.\n• பரிகாரம்: நடராஜப் பெருமானை வழிபட இன்னல்கள் தீரும்.";
      case 6: // புனர்பூசம்
        return "புனர்பூசம் (Punarvasu) $padaText\n\nவாழ்த்துகள்! நீங்கள் புனர்பூசம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். ஸ்ரீராமச்சந்திர மூர்த்தி பிறந்த நட்சத்திரமான இதில் பிறந்த நீங்கள், நற்பண்புகள் நிறைந்தவர்.\n\n• தன்மை: சகிப்புத்தன்மை, விட்டுக்கொடுக்கும் குணம் கொண்டவர். மீண்டும் மீண்டும் முயற்சி செய்து வெற்றி பெறுவீர்கள்.\n• பரிகாரம்: ஸ்ரீராமரை வழிபட குடும்பத்தில் அமைதி நிலவும்.";
      case 7: // பூசம்
        return "பூசம் (Pushya) $padaText\n\nவாழ்த்துகள்! நீங்கள் பூசம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நட்சத்திரங்களின் ராஜா என்று அழைக்கப்படும் இதில் பிறந்த நீங்கள், தர்மம் தவறாதவர்.\n\n• தன்மை: மற்றவர்களுக்கு உதவும் குணம், அமைதி மற்றும் பொறுமை மிக்கவர். ஆன்மீகத்தில் நாட்டம் இருக்கும்.\n• பரிகாரம்: சனிக்கிழமை ஆஞ்சநேயரை வழிபட நன்மைகள் பெருகும்.";
      case 8: // ஆயில்யம்
        return "ஆயில்யம் (Ashlesha) $padaText\n\nவாழ்த்துகள்! நீங்கள் ஆயில்யம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். புத்திசாலித்தனம் மற்றும் சாதுர்யம் நிறைந்த நீங்கள், பேச்சால் எவரையும் வெல்வீர்கள்.\n\n• தன்மை: கூர்மையான மதிநுட்பம். ரகசியங்களைக் காப்பதில் வல்லவர். கடின உழைப்பாளி.\n• பரிகாரம்: ஆதிசேஷன் அல்லது நாகராஜரை வழிபட தோஷங்கள் நீங்கும்.";
      case 9: // மகம்
        return "மகம் (Magha) $padaText\n\nவாழ்த்துகள்! நீங்கள் மகம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். \"மகம் ஜகத்தை ஆளும்\" என்பதற்கேற்ப, நீங்கள் கம்பீரமானவர்.\n\n• தன்மை: முன்னோர்களின் ஆசி பெற்றவர். கௌரவம் மற்றும் நேர்மைக்கு முக்கியத்துவம் தருவீர்கள்.\n• பரிகாரம்: சூரியனார் கோயில் வழிபாடு அல்லது பித்ரு வழிபாடு உங்களுக்கு மேன்மை தரும்.";
      case 10: // பூரம்
        return "பூரம் (Purva Phalguni) $padaText\n\nவாழ்த்துகள்! நீங்கள் பூரம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். மகிழ்ச்சி மற்றும் ஆடம்பரத்தை விரும்பும் நீங்கள், ரசனை மிக்கவர்.\n\n• தன்மை: கலைகளில் ஆர்வம், வசீகரப் பேச்சு. நட்பு வட்டாரத்தில் செல்வாக்கு மிக்கவராக இருப்பீர்கள்.\n• பரிகாரம்: ஸ்ரீ ஆண்டாள் நாச்சியாரை வழிபட வாழ்க்கை வசந்தமாகும்.";
      case 11: // உத்திரம்
        return "உத்திரம் (Uttara Phalguni) $padaText\n\nவாழ்த்துகள்! நீங்கள் உத்திரம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். மற்றவர்களுக்கு உதவும் நல்ல மனம் கொண்ட நீங்கள், பொறுப்பானவர்.\n\n• தன்மை: கடமை உணர்வு, தாராள குணம். ஒரு காரியத்தை எடுத்தால் அதை நேர்த்தியாக முடிப்பீர்கள்.\n• பரிகாரம்: சூரிய பகவானை வழிபட புகழும் அந்தஸ்தும் கிடைக்கும்.";
      case 12: // அஸ்தம்
        return "அஸ்தம் (Hasta) $padaText\n\nவாழ்த்துகள்! நீங்கள் அஸ்தம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். உங்கள் கைகளில் மந்திர சக்தி உள்ளது. கைவேலைப்பாடுகள் அல்லது தொழில்நுட்பத்தில் வல்லவர்.\n\n• தன்மை: நகைச்சுவை உணர்வு, விடாமுயற்சி. எதையும் திட்டமிட்டுச் செயல்படுத்துவீர்கள்.\n• பரிகாரம்: காயத்ரி தேவியை வழிபட புத்தி பிரகாசிக்கும்.";
      case 13: // சித்திரை
        return "சித்திரை (Chitra) $padaText\n\nவாழ்த்துகள்! நீங்கள் சித்திரை நட்சத்திரத்தில் பிறந்துள்ளீர்கள். சிற்பி விஸ்வகர்மாவின் அம்சம் கொண்ட நீங்கள், அழகான பொருட்களை உருவாக்க விரும்புவீர்கள்.\n\n• தன்மை: தைரியம், படைப்பாற்றல். எதிர்ப்புகளைக் கண்டு அஞ்சாதவர். தனித்துவமான ஆளுமை.\n• பரிகாரம்: சித்ரகுப்தரை வழிபட பாவங்கள் விலகி புண்ணியம் சேரும்.";
      case 14: // சுவாதி
        return "சுவாதி (Swati) $padaText\n\nவாழ்த்துகள்! நீங்கள் சுவாதி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். சுதந்திரத்தை விரும்பும் நீங்கள், காற்றில் அசையும் தீபம் போல எப்போதும் சுறுசுறுப்பானவர்.\n\n• தன்மை: நிதானமான வளர்ச்சி, நேர்மை. மற்றவர்களுக்குப் பயப்படாமல் உண்மையை பேசுவீர்கள்.\n• பரிகாரம்: நரசிம்ம மூர்த்தியை வழிபட வெற்றிகள் தேடி வரும்.";
      case 15: // விசாகம்
        return "விசாகம் (Vishakha) $padaText\n\nவாழ்த்துகள்! நீங்கள் விசாகம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். லட்சியவாதியான நீங்கள், எதையும் சாதிக்கும் மன உறுதி கொண்டவர்.\n\n• தன்மை: விடாமுயற்சி, பல துறைகளில் ஞானம். மற்றவர்களுக்கு ஒரு முன்னுதாரணமாகத் திகழ்வீர்கள்.\n• பரிகாரம்: முருகப் பெருமானை (விசாகன்) வழிபட மேன்மை உண்டாகும்.";
      case 16: // அனுஷம்
        return "அனுஷம் (Anuradha) $padaText\n\nவாழ்த்துகள்! நீங்கள் அனுஷம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நட்பிற்கு இலக்கணம் வகுக்கும் நீங்கள், மென்மையான உள்ளம் கொண்டவர்.\n\n• தன்மை: அமைதி, பொறுமை. வெளியூர் அல்லது வெளிநாடுகளில் சாதிக்கும் யோகம் உண்டு.\n• பரிகாரம்: மகாலட்சுமியை வழிபட செல்வம் பெருகும்.";
      case 17: // கேட்டை
        return "கேட்டை (Jyeshta) $padaText\n\nவாழ்த்துகள்! நீங்கள் கேட்டை நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நிர்வாகத் திறமை மிக்க நீங்கள், குடும்பத்திலும் சமூகத்திலும் மூத்தவராக மதிக்கப்படுவீர்கள்.\n\n• தன்மை: தைரியம், பாதுகாப்பு உணர்வு. பிறரை வழிநடத்தும் ஆற்றல் உங்களுக்கு இயல்பிலேயே உண்டு.\n• பரிகாரம்: ஹயக்ரீவரை வழிபட கல்வி மற்றும் அறிவு வளரும்.";
      case 18: // மூலம்
        return "மூலம் (Moola) $padaText\n\nவாழ்த்துகள்! நீங்கள் மூலம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். ஆணிவேர் போன்ற பிடிப்பு கொண்ட நீங்கள், எதையும் அடிப்படையிலிருந்து ஆராய்பவர்.\n\n• தன்மை: ஆன்மீக ஞானம், எதையும் தைரியமாக எதிர்கொள்ளும் குணம். கொள்கை பிடிப்பு மிக்கவர்.\n• பரிகாரம்: ஆஞ்சநேயரை வழிபட அஷ்ட ஐஸ்வர்யங்களும் கிட்டும்.";
      case 19: // பூராடம்
        return "பூராடம் (Purva Ashadha) $padaText\n\nவாழ்த்துகள்! நீங்கள் பூராடம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். வெற்றி பெறுவதையே குறிக்கோளாகக் கொண்ட நீங்கள், எப்போதும் உற்சாகமானவர்.\n\n• தன்மை: வாக்கு சாதுர்யம், கலை ஈடுபாடு. தோல்விகளைக் கண்டு சோர்ந்து போகாத மனப்பக்குவம்.\n• பரிகாரம்: ஜலகண்டேஸ்வரரை அல்லது சிவபெருமானை வழிபட வளம் பெருகும்.";
      case 20: // உத்திராடம்
        return "உத்திராடம் (Uttara Ashadha) $padaText\n\nவாழ்த்துகள்! நீங்கள் உத்திராடம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். வெற்றி தேவதையின் அம்சம் கொண்ட நீங்கள், கௌரவம் மிக்கவர்.\n\n• தன்மை: அமைதி, எதார்த்தமான சிந்தனை. பிறரால் மதிக்கப்படும் பண்பு உங்களுக்கு உண்டு.\n• பரிகாரம்: விநாயகரை வழிபட எடுத்த காரியங்கள் தடையின்றி முடியும்.";
      case 21: // திருவோணம்
        return "திருவோணம் (Shravana) $padaText\n\nவாழ்த்துகள்! நீங்கள் திருவோணம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நல்லவற்றைக் கேட்பதில் ஆர்வம் கொண்ட நீங்கள், கற்றறிந்த மேதையாகத் திகழ்வீர்கள்.\n\n• தன்மை: ஒழுக்கம், மரியாதை மற்றும் பொறுமை. உங்கள் பேச்சிற்குச் சமூகத்தில் நல்ல மதிப்பு இருக்கும்.\n• பரிகாரம்: விஷ்ணு பகவானை (பெருமாள்) வழிபட யோகங்கள் உண்டாகும்.";
      case 22: // அவிட்டம்
        return "அவிட்டம் (Dhanishta) $padaText\n\nவாழ்த்துகள்! நீங்கள் அவிட்டம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். செல்வம் மற்றும் இசையில் நாட்டம் கொண்ட நீங்கள், செல்வாக்கு மிக்கவர்.\n\n• தன்மை: தாராள குணம், தைரியம். சவால்களைச் சந்தோஷமாக எதிர்கொள்வீர்கள்.\n• பரிகாரம்: துர்க்கை அம்மன் அல்லது முருகனை வழிபட வாழ்வு உயரும்.";
      case 23: // சதயம்
        return "சதயம் (Shatabhisha) $padaText\n\nவாழ்த்துகள்! நீங்கள் சதயம் நட்சத்திரத்தில் பிறந்துள்ளீர்கள். ஆயிரம் நட்சத்திரங்களின் ஆற்றல் கொண்ட நீங்கள், ஒரு சிறந்த ஆராய்ச்சியாளர்.\n\n• தன்மை: எதையும் ரகசியமாகச் செய்து முடிப்பீர்கள். தீர்க்க முடியாத பிரச்சனைகளையும் தீர்க்கும் ஆற்றல் உண்டு.\n• பரிகாரம்: சிவபெருமானை (மிருத்யுஞ்சய மந்திரம்) வழிபட ஆரோக்கியம் பெருகும்.";
      case 24: // பூரட்டாதி
        return "பூரட்டாதி (Purva Bhadrapada) $padaText\n\nவாழ்த்துகள்! நீங்கள் பூரட்டாதி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நேர்மையும் ஒழுக்கமும் உங்கள் இரு கண்கள். சமூக மாற்றத்தை விரும்புபவர் நீங்கள்.\n\n• தன்மை: ஆன்மீக ஆர்வம், இரக்க குணம். மற்றவர்களுக்கு நீதி வழங்கும் உயர்ந்த நிலையில் இருப்பீர்கள்.\n• பரிகாரம்: குபேரனை அல்லது குரு பகவானை வழிபட செல்வம் சேரும்.";
      case 25: // உத்திரட்டாதி
        return "உத்திரட்டாதி (Uttara Bhadrapada) $padaText\n\nவாழ்த்துகள்! நீங்கள் உத்திரட்டாதி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். அமைதியும் ஞானமும் கொண்ட நீங்கள், அனைவரிடமும் அன்பாகப் பழகுவீர்கள்.\n\n• தன்மை: ஆழ்ந்த சிந்தனை, மற்றவர்களின் துன்பத்தைப் போக்கும் குணம். நிலையான செல்வம் உங்களுக்கு உண்டு.\n• பரிகாரம்: சனி பகவானையும் ஈஸ்வரனையும் வழிபட நிம்மதி நிலைக்கும்.";
      case 26: // ரேவதி
        return "ரேவதி (Revati) $padaText\n\nவாழ்த்துகள்! நீங்கள் ரேவதி நட்சத்திரத்தில் பிறந்துள்ளீர்கள். நட்சத்திர மண்டலத்தின் கடைசி நட்சத்திரமான இதில் பிறந்த நீங்கள், முழுமையானவர்.\n\n• தன்மை: மென்மையான இதயம், கலைத்திறன் மற்றும் தெய்வீக பற்று. அனைவரையும் நேசிக்கும் பண்பு கொண்டவர்.\n• பரிகாரம்: மகாவிஷ்ணுவை வழிபட வாழ்வின் நோக்கம் நிறைவேறும்.";
      default:
        return "$nakshatraName ($padaText)";
    }
  }

  static String getDetailedLagnaPalan(String? lagnaKey) {
    if (lagnaKey == null) return "-";
    switch (lagnaKey) {
      case 'Aries':
        return "மேஷ லக்ன பலன்கள்: ஆளுமையும் விதியும்\n\nவாழ்த்துகள்! நீங்கள் மேஷ லக்னத்தில் பிறந்துள்ளீர்கள். ஜோதிட மண்டலத்தின் முதல் ராசியான மேஷத்தில் உங்கள் லக்னம் அமைந்திருப்பது, நீங்கள் ஒரு \"இயற்கை படைப்பாளி\" மற்றும் \"முன்னோடி\" என்பதை உணர்த்துகிறது. செவ்வாய் பகவானை அதிபதியாகக் கொண்ட இந்த லக்னத்தில் பிறந்த உங்களுக்கான விரிவான வாழ்க்கை வழிகாட்டி இதோ:\n\n1. லக்னத்தின் அடிப்படை தன்மை: மேஷ லக்னம் என்பது நெருப்புத் தத்துவத்தைக் கொண்டது. நீங்கள் எப்போதும் சுறுசுறுப்பாக இயங்கிக் கொண்டே இருப்பீர்கள். தோல்விகளைக் கண்டு அஞ்சாமல், மீண்டும் மீண்டும் முயற்சிக்கும் \"பீனிக்ஸ்\" பறவை போன்ற குணம் உங்களுக்கு உண்டு.\n\n2. உடலமைப்பு மற்றும் குணாதிசயம்: கம்பீரமான தோற்றம், கூர்மையான நாசி, எடுப்பான கண்கள். வெளிப்படையாகப் பேசும் நேர்மையாளர். கோபம் வந்தாலும் உடனே ஆறிவிடும்.\n\n3. கல்வி மற்றும் தொழில்: தொழில்நுட்பம், மருத்துவம், ராணுவம் அல்லது சட்டம் சார்ந்த துறைகளில் சிறந்து விளங்குவீர்கள். சிறந்த நிர்வாகி.\n\n4. பண நிலை: பணப்புழக்கம் எப்போதும் இருக்கும். 32 முதல் 40 வயது வரை பொற்காலம்.\n\n5. திருமணம்: துலாம் ஏழாம் இடம் என்பதால், கலை ரசனை மிக்க துணை அமைவார்.\n\n6. ஆரோக்கியம்: உஷ்ணம் சம்பந்தப்பட்ட நோய்களில் கவனம் தேவை. கார உணவைத் தவிர்க்கவும்.\n\n7. வழிபாடு: செவ்வாய்க்கிழமை முருகப்பெருமான் வழிபாடு தடைகளை நீக்கும்.";
      case 'Taurus':
        return "ரிஷப லக்ன பலன்கள்\n\nவாழ்த்துகள்! நீங்கள் ரிஷப லக்னத்தில் பிறந்துள்ளீர்கள். சுக்கிரனை அதிபதியாகக் கொண்ட ஸ்திர லக்னமான இதில் பிறந்த நீங்கள், நிதானத்திற்கும் பொறுமைக்கும் பெயர் பெற்றவர்.\n\n• அடிப்படை தன்மை: நீங்கள் எதையும் யோசித்து நிதானமாகச் செய்பவர். ஆடம்பரமான மற்றும் அழகான பொருட்களை விரும்புவீர்கள்.\n• குணாதிசயம்: கலை ரசனை மிக்கவர். அமைதியாகத் தெரிந்தாலும், கோபம் வந்தால் அடங்க மாட்டீர்கள்.\n• கல்வி & தொழில்: வங்கித் துறை, கலைத்துறை, அழகு சாதனப் பொருட்கள் அல்லது உணவு சார்ந்த தொழில்களில் வெற்றி பெறுவீர்கள்.\n• குடும்பம்: அமைதியான குடும்ப வாழ்க்கை அமையும்.\n• ஆரோக்கியம்: தொண்டை மற்றும் கழுத்து சம்பந்தப்பட்ட கவனம் தேவை.\n• பரிகாரம்: வெள்ளிக்கிழமை மகாலட்சுமி வழிபாடு யோகம் தரும்.";
      case 'Gemini':
        return "மிதுன லக்ன பலன்கள்\n\nவாழ்த்துகள்! நீங்கள் மிதுன லக்னத்தில் பிறந்துள்ளீர்கள். புதன் பகவானை அதிபதியாகக் கொண்ட இந்த லக்னத்தில் பிறந்த நீங்கள், அறிவுத்திறன் மிக்கவர்.\n\n• அடிப்படை தன்மை: பேச்சாற்றல் மிக்கவர். நகைச்சுவை உணர்வு அதிகம். மாறும் தன்மையாளர்.\n• குணாதிசயம்: மாற்றங்களை விரும்புவீர்கள். எதிலும் ஒரு புதுமையை எதிர்பார்ப்பீர்கள்.\n• கல்வி & தொழில்: எழுத்துத் துறை, தகவல் தொடர்பு, கணிதம் அல்லது மென்பொருள் துறையில் ஜொலிப்பீர்கள்.\n• குடும்பம்: நண்பர்களைப் போன்ற உறவுகள் அமையும்.\n• ஆரோக்கியம்: நரம்புத் தளர்ச்சி மற்றும் நுரையீரல் சம்பந்தமான கவனம் தேவை.\n• பரிகாரம்: புதன்கிழமை விஷ்ணு வழிபாடு நன்மை தரும்.";
      case 'Cancer':
