      case 'Aquarius':
        return "கும்ப லக்ன பலன்கள்\n\nவாழ்த்துகள்! நீங்கள் கும்ப லக்னத்தில் பிறந்துள்ளீர்கள். சனி பகவானை அதிபதியாகக் கொண்ட இந்த லக்னத்தில் பிறந்த நீங்கள், மனிதாபிமானம் கொண்டவர்.\n\n• அடிப்படை தன்மை: சமூகச் சிந்தனையாளர். புதுமையான மற்றும் புரட்சிகரமான கருத்துக்கள் கொண்டவர்.\n• குணாதிசயம்: எல்லோரையும் சமமாகப் பார்ப்பீர்கள். மற்றவர்களிடமிருந்து தனித்துத் தெரிவீர்கள்.\n• கல்வி & தொழில்: அறிவியல், ஆராய்ச்சி அல்லது தகவல் தொழில்நுட்பம் சார்ந்த பிரிவுகள் சிறந்தது.\n• குடும்பம்: சமூகத்திற்கு அதிக முக்கியத்துவம் தருவீர்கள்.\n• ஆரோக்கியம்: கால் பாதங்கள் மற்றும் நரம்புத் தளர்ச்சி கவனம் தேவை.\n• பரிகாரம்: சிவ வழிபாடு மற்றும் அன்னதானம் செய்வது நன்மை தரும்.";
      case 'Pisces':
        return "மீன லக்ன பலன்கள்\n\nவாழ்த்துகள்! நீங்கள் மீன லக்னத்தில் பிறந்துள்ளீர்கள். குரு பகவானை அதிபதியாகக் கொண்ட இந்த லக்னத்தில் பிறந்த நீங்கள், ஞானம் மிக்கவர்.\n\n• அடிப்படை தன்மை: மென்மையான சுபாவம். அனைவரும் அன்புடன் பழகுபவர்.\n• குணாதிசயம்: மற்றவர்களுக்கு உதவுவதில் மகிழ்ச்சி. ஆன்மீக ஈடுபாடு அதிகம்.\n• கல்வி & தொழில்: கல்வித்துறை, யோகா-தியானம் அல்லது ஆன்மீகப் பணிகள் சிறந்தது.\n• குடும்பம்: அமைதியான குடும்பம் அமையும்.\n• ஆரோக்கியம்: கண்கள் மற்றும் பாதங்கள் சார்ந்த பிரச்சனைகளில் கவனம் தேவை.\n• பரிகாரம்: வியாழக்கிழமை குரு வழிபாடு வாழ்வை மேம்படுத்தும்.";
      default:
        return "${KPService.TAMIL_SIGNS[lagnaKey] ?? lagnaKey} லக்னம்";
    }
  }

